<?php
/** Recorded-video commands, captions, playlists, playback and interactions. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Videos {
	public static function create_channel($data){if(!VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,null,'create_channel'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot create a channel.',VWLB_TEXT_DOMAIN),403);$title=VWLB_Helpers::text($data['title']??'');if(!$title)return VWLB_Helpers::error('vwlb_title_required',__('Title is required.',VWLB_TEXT_DOMAIN));global $wpdb;$now=VWLB_Helpers::now();$public=VWLB_Helpers::public_id('chn');$slug=sanitize_title($data['slug']??$title.'-'.substr($public,-6));$wpdb->insert(VWLB_Helpers::table('channels'),array('public_id'=>$public,'owner_id'=>get_current_user_id(),'title'=>$title,'slug'=>$slug,'description'=>VWLB_Helpers::textarea($data['description']??''),'branding_json'=>VWLB_Helpers::json_encode($data['branding']??array()),'roles_json'=>VWLB_Helpers::json_encode(array('owner'=>get_current_user_id())),'status'=>'active','visibility'=>VWLB_Helpers::enum($data['visibility']??'public',VWLB_Contracts::VISIBILITIES,'public'),'created_at'=>$now,'updated_at'=>$now));$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('channel',$id,'create','','active');VWLB_Helpers::outbox('ChannelCreated','channel',$id,array('public_id'=>$public));return VWLB_Repository::find('channels',$id);}
	public static function create_playlist($data){if(!VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,null,'create_playlist'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot create a playlist.',VWLB_TEXT_DOMAIN),403);$title=VWLB_Helpers::text($data['title']??'');if(!$title)return VWLB_Helpers::error('vwlb_title_required',__('Title is required.',VWLB_TEXT_DOMAIN));$channel_id=absint($data['channel_id']??0);if($channel_id){$channel=VWLB_Repository::find('channels',$channel_id);if(!$channel||!VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,$channel,'create_playlist'))return VWLB_Helpers::error('vwlb_channel_forbidden',__('The channel is unavailable.',VWLB_TEXT_DOMAIN),404);}global $wpdb;$now=VWLB_Helpers::now();$public=VWLB_Helpers::public_id('pl');$wpdb->insert(VWLB_Helpers::table('playlists'),array('public_id'=>$public,'channel_id'=>$channel_id,'owner_id'=>get_current_user_id(),'title'=>$title,'slug'=>sanitize_title($data['slug']??$title.'-'.substr($public,-6)),'description'=>VWLB_Helpers::textarea($data['description']??''),'status'=>'active','visibility'=>VWLB_Helpers::enum($data['visibility']??'public',VWLB_Contracts::VISIBILITIES,'public'),'created_at'=>$now,'updated_at'=>$now));$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('playlist',$id,'create','','active');return VWLB_Repository::find('playlists',$id);}
	public static function set_playlist_items($playlist_id,$video_ids,$expected_version){$playlist=VWLB_Repository::find('playlists',$playlist_id);if(!$playlist)return VWLB_Helpers::error('vwlb_playlist_missing',__('Playlist not found.',VWLB_TEXT_DOMAIN),404);if(!VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,$playlist,'edit_playlist'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot edit this playlist.',VWLB_TEXT_DOMAIN),403);$video_ids=array_values(array_unique(array_filter(array_map('absint',(array)$video_ids))));if(count($video_ids)>500)return VWLB_Helpers::error('vwlb_playlist_too_large',__('Playlist item limit exceeded.',VWLB_TEXT_DOMAIN));return VWLB_DB::transaction(function()use($playlist,$video_ids,$expected_version){global $wpdb;$locked=VWLB_Repository::find('playlists',$playlist['id'],true);if((int)$locked['version']!==(int)$expected_version)return VWLB_Helpers::error('vwlb_version_conflict',__('Playlist changed. Refresh and retry.',VWLB_TEXT_DOMAIN),409);$wpdb->delete(VWLB_Helpers::table('playlist_items'),array('playlist_id'=>$playlist['id']),array('%d'));foreach($video_ids as $order=>$video_id){$video=VWLB_Repository::find('videos',$video_id);if(!$video)return VWLB_Helpers::error('vwlb_video_missing',__('A playlist video was not found.',VWLB_TEXT_DOMAIN),404);$wpdb->insert(VWLB_Helpers::table('playlist_items'),array('playlist_id'=>$playlist['id'],'video_id'=>$video_id,'sort_order'=>$order,'created_at'=>VWLB_Helpers::now(),'updated_at'=>VWLB_Helpers::now()),array('%d','%d','%d','%s','%s'));} $updated=VWLB_Repository::update_versioned('playlists',$playlist['id'],$expected_version,array(),array());VWLB_Helpers::audit('playlist',$playlist['id'],'reorder','','','Playlist membership replaced',array('count'=>count($video_ids)));return $updated;});}
	public static function create($data,$idempotency_key){if(!VWLB_Security::can(VWLB_Contracts::CAP_SUBMIT,null,'create_video'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot create videos.',VWLB_TEXT_DOMAIN),403);$title=VWLB_Helpers::text($data['title']??'');if(!$title)return VWLB_Helpers::error('vwlb_title_required',__('Title is required.',VWLB_TEXT_DOMAIN));$provider=VWLB_Helpers::enum($data['provider']??'local',array_keys(VWLB_Providers::all()),'local');$normalized=array('provider'=>$provider,'source_url'=>'','embed_url'=>'','provider_ref'=>'');if(!empty($data['source_url'])){$normalized=VWLB_Providers::normalize($provider,$data['source_url']);if(is_wp_error($normalized))return $normalized;}$visibility=VWLB_Helpers::enum($data['visibility']??'private',VWLB_Contracts::VISIBILITIES,'private');$patient=!empty($data['patient_case']);$consent=VWLB_Helpers::enum($data['consent_status']??($patient?'missing':'not_patient_case'),array('not_patient_case','missing','documented','anonymized','approved'),'not_patient_case');if($patient&&!in_array($consent,array('documented','anonymized','approved'),true))return VWLB_Helpers::error('vwlb_patient_consent_required',__('Patient-case media requires documented consent and anonymization review.',VWLB_TEXT_DOMAIN),422);$asset_id=absint($data['asset_id']??0);if($asset_id){$asset=VWLB_Repository::find('media_assets',$asset_id);if(!$asset||!VWLB_Security::can(VWLB_Contracts::CAP_SUBMIT,$asset,'link_asset'))return VWLB_Helpers::error('vwlb_asset_forbidden',__('The media asset is unavailable.',VWLB_TEXT_DOMAIN),404);}$channel_id=absint($data['channel_id']??0);if($channel_id){$channel=VWLB_Repository::find('channels',$channel_id);if(!$channel||!VWLB_Security::can(VWLB_Contracts::CAP_SUBMIT,$channel,'create_video'))return VWLB_Helpers::error('vwlb_channel_forbidden',__('The channel is unavailable.',VWLB_TEXT_DOMAIN),404);}$hash=hash('sha256',VWLB_Helpers::json_encode($data));$idem=VWLB_Security::idempotency_begin($idempotency_key,'create_video',$hash);if(is_wp_error($idem))return $idem;if($idem['replay'])return $idem['response'];global $wpdb;$now=VWLB_Helpers::now();$public=VWLB_Helpers::public_id('vid');$status=$asset_id?'processing':'review';$wpdb->insert(VWLB_Helpers::table('videos'),array('public_id'=>$public,'channel_id'=>$channel_id,'asset_id'=>$asset_id,'owner_id'=>get_current_user_id(),'title'=>$title,'slug'=>sanitize_title($data['slug']??$title.'-'.substr($public,-6)),'description'=>VWLB_Helpers::textarea($data['description']??''),'excerpt'=>VWLB_Helpers::text($data['excerpt']??'',500),'topics_json'=>VWLB_Helpers::json_encode(array_values(array_unique(array_map('sanitize_key',(array)($data['topics']??array()))))),'language'=>VWLB_Helpers::text($data['language']??'en-US',20),'provider'=>$normalized['provider'],'source_url'=>$normalized['source_url']??'','embed_url'=>$normalized['embed_url']??'','thumbnail_id'=>absint($data['thumbnail_id']??0),'duration_seconds'=>VWLB_Helpers::duration_seconds($data['duration']??0),'visibility'=>$visibility,'status'=>$status,'scheduled_at'=>VWLB_Helpers::datetime($data['scheduled_at']??null),'consent_status'=>$consent,'rights_status'=>VWLB_Helpers::enum($data['rights_status']??'declared',array('declared','verified','disputed','restricted'),'declared'),'rights_json'=>VWLB_Helpers::json_encode($data['rights']??array()),'access_policy_json'=>VWLB_Helpers::json_encode($data['access_policy']??array()),'created_at'=>$now,'updated_at'=>$now));if(false===$wpdb->last_error&&0===(int)$wpdb->insert_id)return VWLB_Helpers::error('vwlb_database_error',__('Video could not be created.',VWLB_TEXT_DOMAIN),500);$id=(int)$wpdb->insert_id;if($asset_id){$wpdb->update(VWLB_Helpers::table('media_assets'),array('source_object_type'=>'video','source_object_id'=>$id,'updated_at'=>$now),array('id'=>$asset_id),array('%s','%d','%s'),array('%d'));}VWLB_Helpers::audit('video',$id,'create','',$status);VWLB_Helpers::outbox('VideoCreated','video',$id,array('public_id'=>$public,'status'=>$status));$response=array('id'=>$id,'public_id'=>$public,'status'=>$status,'version'=>1);VWLB_Security::idempotency_finish($idempotency_key,'create_video',$response);return $response;}
	public static function publish($video_id,$expected_version,$schedule=null){$video=VWLB_Repository::find('videos',$video_id);if(!$video)return VWLB_Helpers::error('vwlb_video_missing',__('Video not found.',VWLB_TEXT_DOMAIN),404);if(!VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,$video,'publish_video'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot publish this video.',VWLB_TEXT_DOMAIN),403);$gate=self::publication_gate($video);if(is_wp_error($gate))return $gate;$to=$schedule?'scheduled':'published';$assert=VWLB_State_Machine::assert('video',$video['status'],$to);if(is_wp_error($assert))return $assert;$changes=array('status'=>$to,'scheduled_at'=>$schedule?VWLB_Helpers::datetime($schedule):null,'published_at'=>$schedule?null:VWLB_Helpers::now());$updated=VWLB_Repository::update_versioned('videos',$video['id'],$expected_version,$changes,array('%s','%s','%s'));if(is_wp_error($updated))return $updated;VWLB_Helpers::audit('video',$video['id'],'publish',$video['status'],$to,'Publication gate passed');VWLB_Helpers::outbox($schedule?'VideoScheduled':'VideoPublished','video',$video['id'],array('public_id'=>$video['public_id']));return $updated;}
	public static function publication_gate($video){global $wpdb;if(!trim((string)$video['title'])||!trim((string)$video['language']))return VWLB_Helpers::error('vwlb_metadata_gate',__('Required video metadata is incomplete.',VWLB_TEXT_DOMAIN),422);if(!in_array($video['rights_status'],array('verified','declared'),true))return VWLB_Helpers::error('vwlb_rights_gate',__('Rights verification is incomplete.',VWLB_TEXT_DOMAIN),422);if(!in_array($video['consent_status'],array('not_patient_case','documented','anonymized','approved'),true))return VWLB_Helpers::error('vwlb_consent_gate',__('Patient privacy review is incomplete.',VWLB_TEXT_DOMAIN),422);if($video['asset_id']){$asset=VWLB_Repository::find('media_assets',$video['asset_id']);if(!$asset||'ready'!==$asset['status']||'passed'!==$asset['scan_status'])return VWLB_Helpers::error('vwlb_asset_not_ready',__('Media processing and scanning must finish before publication.',VWLB_TEXT_DOMAIN),422);}if((bool)apply_filters('vwlb_captions_required',true,$video)){$caption=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.VWLB_Helpers::table('captions').' WHERE video_id=%d AND status=%s',$video['id'],'published'));if(!$caption)return VWLB_Helpers::error('vwlb_caption_gate',__('At least one reviewed caption track is required.',VWLB_TEXT_DOMAIN),422);}return (bool)apply_filters('vwlb_video_publication_gate',true,$video)?true:VWLB_Helpers::error('vwlb_policy_gate',__('A publication policy gate did not pass.',VWLB_TEXT_DOMAIN),422);}
	public static function add_caption($video_id,$data){$video=VWLB_Repository::find('videos',$video_id);if(!$video)return VWLB_Helpers::error('vwlb_video_missing',__('Video not found.',VWLB_TEXT_DOMAIN),404);if(!VWLB_Security::can(VWLB_Contracts::CAP_SUBMIT,$video,'add_caption'))return VWLB_Helpers::error('vwlb_forbidden',__('You cannot add captions.',VWLB_TEXT_DOMAIN),403);$content=(string)($data['content']??'');if(strlen($content)>2*1024*1024)return VWLB_Helpers::error('vwlb_caption_too_large',__('Caption file is too large.',VWLB_TEXT_DOMAIN),413);$format=VWLB_Helpers::enum($data['format']??'vtt',array('vtt','srt','ttml'),'vtt');if('vtt'===$format&&0!==strpos(ltrim($content),'WEBVTT'))return VWLB_Helpers::error('vwlb_invalid_vtt',__('WebVTT captions must begin with WEBVTT.',VWLB_TEXT_DOMAIN),422);global $wpdb;$now=VWLB_Helpers::now();$status=VWLB_Security::can(VWLB_Contracts::CAP_PUBLISH,$video,'review_caption')?'published':'review';$version=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(MAX(version),0)+1 FROM '.VWLB_Helpers::table('captions').' WHERE video_id=%d AND language=%s AND kind=%s',$video['id'],VWLB_Helpers::text($data['language']??'en-US',20),VWLB_Helpers::enum($data['kind']??'captions',array('captions','subtitles','transcript'),'captions')));$wpdb->insert(VWLB_Helpers::table('captions'),array('public_id'=>VWLB_Helpers::public_id('cap'),'video_id'=>$video['id'],'language'=>VWLB_Helpers::text($data['language']??'en-US',20),'kind'=>VWLB_Helpers::enum($data['kind']??'captions',array('captions','subtitles','transcript'),'captions'),'source'=>VWLB_Helpers::enum($data['source']??'manual',array('manual','imported','machine_draft'),'manual'),'format'=>$format,'content'=>$content,'status'=>$status,'quality_score'=>isset($data['quality_score'])?(float)$data['quality_score']:null,'version'=>$version,'created_by'=>get_current_user_id(),'reviewed_by'=>'published'===$status?get_current_user_id():0,'created_at'=>$now,'updated_at'=>$now));$id=(int)$wpdb->insert_id;VWLB_Helpers::audit('caption',$id,'create','',$status);return array('id'=>$id,'status'=>$status,'version'=>$version);}
	public static function playback($video_id){$video=VWLB_Repository::video_bundle($video_id);if(!$video||!VWLB_Security::can_view($video))return VWLB_Helpers::error('vwlb_not_found',__('Video not found.',VWLB_TEXT_DOMAIN),404);$provider=VWLB_Providers::get($video['provider']);if(!$provider)return VWLB_Helpers::error('vwlb_provider_missing',__('Playback provider is unavailable.',VWLB_TEXT_DOMAIN),503);$payload=$provider->playback($video,VWLB_Security::claims());if(is_wp_error($payload))return $payload;$session=self::playback_session($video);if(!in_array($video['visibility'],array('public','unlisted'),true)){$secure=apply_filters('vwlb_secure_playback_grant','',$video,$payload,$session,VWLB_Security::claims());if(!$secure)return VWLB_Helpers::error('vwlb_secure_delivery_required',__('Secure playback delivery is not configured.',VWLB_TEXT_DOMAIN),503);$payload['url']=esc_url_raw($secure);}self::count_view($video);return array('video'=>VWLB_Repository::public_video_dto($video),'playback'=>$payload,'session'=>$session);}
	private static function playback_session($video){global $wpdb;$user=get_current_user_id();$now=VWLB_Helpers::now();$token=VWLB_Helpers::public_id('play');$hash=hash_hmac('sha256',$token,wp_salt('logged_in'));if($user){$row=$wpdb->get_row($wpdb->prepare('SELECT id,public_id,progress_seconds FROM '.VWLB_Helpers::table('playback_sessions').' WHERE user_id=%d AND object_type=%s AND object_id=%d',$user,'video',$video['id']),ARRAY_A);if($row){$wpdb->update(VWLB_Helpers::table('playback_sessions'),array('token_hash'=>$hash,'updated_at'=>$now,'expires_at'=>gmdate('Y-m-d H:i:s',time()+30*DAY_IN_SECONDS)),array('id'=>$row['id']));return array('token'=>$token,'resume_seconds'=>(int)$row['progress_seconds']);}}$wpdb->insert(VWLB_Helpers::table('playback_sessions'),array('public_id'=>VWLB_Helpers::public_id('ses'),'user_id'=>$user,'object_type'=>'video','object_id'=>$video['id'],'token_hash'=>$hash,'progress_seconds'=>0,'duration_seconds'=>(int)$video['duration_seconds'],'ip_hash'=>VWLB_Helpers::ip_hash(),'user_agent_hash'=>VWLB_Helpers::ua_hash(),'created_at'=>$now,'updated_at'=>$now,'expires_at'=>gmdate('Y-m-d H:i:s',time()+($user?30*DAY_IN_SECONDS:2*HOUR_IN_SECONDS))));return array('token'=>$token,'resume_seconds'=>0);}
	private static function count_view($video){if(is_admin()||current_user_can(VWLB_Contracts::CAP_MANAGE))return;$ua=strtolower((string)($_SERVER['HTTP_USER_AGENT']??''));if(preg_match('/bot|crawler|spider|preview|monitor/',$ua))return;$key='vwlb_view_'.hash('sha256',$video['id'].'|'.get_current_user_id().'|'.VWLB_Helpers::ip_hash());if(get_transient($key))return;set_transient($key,1,6*HOUR_IN_SECONDS);global $wpdb;$wpdb->query($wpdb->prepare('UPDATE '.VWLB_Helpers::table('videos').' SET view_count=view_count+1 WHERE id=%d',$video['id']));}
	public static function clear_history(){if(!is_user_logged_in())return VWLB_Helpers::error('vwlb_login_required',__('Sign in to clear history.',VWLB_TEXT_DOMAIN),401);global $wpdb;$removed=$wpdb->delete(VWLB_Helpers::table('playback_sessions'),array('user_id'=>get_current_user_id(),'object_type'=>'video'),array('%d','%s'));VWLB_Helpers::audit('history',get_current_user_id(),'clear','','complete','User cleared private watch history');return array('removed'=>(int)$removed);}
	public static function progress($video_id,$seconds,$duration=0){if(!is_user_logged_in())return VWLB_Helpers::error('vwlb_login_required',__('Sign in to save progress.',VWLB_TEXT_DOMAIN),401);$video=VWLB_Repository::find('videos',$video_id);if(!$video||!VWLB_Security::can_view($video))return VWLB_Helpers::error('vwlb_not_found',__('Video not found.',VWLB_TEXT_DOMAIN),404);global $wpdb;$seconds=max(0,min((int)$seconds,max((int)$duration,(int)$video['duration_seconds'],DAY_IN_SECONDS)));$duration=max((int)$duration,(int)$video['duration_seconds']);$completed=$duration>0&&$seconds>=(int)floor($duration*.9);$table=VWLB_Helpers::table('playback_sessions');$existing=$wpdb->get_row($wpdb->prepare("SELECT id FROM $table WHERE user_id=%d AND object_type='video' AND object_id=%d",get_current_user_id(),$video['id']),ARRAY_A);$data=array('progress_seconds'=>$seconds,'duration_seconds'=>$duration,'completed'=>$completed?1:0,'updated_at'=>VWLB_Helpers::now(),'expires_at'=>gmdate('Y-m-d H:i:s',time()+30*DAY_IN_SECONDS));if($existing)$wpdb->update($table,$data,array('id'=>$existing['id']));else{$data=array_merge($data,array('public_id'=>VWLB_Helpers::public_id('ses'),'user_id'=>get_current_user_id(),'object_type'=>'video','object_id'=>$video['id'],'created_at'=>VWLB_Helpers::now()));$wpdb->insert($table,$data);}return array('saved'=>true,'progress_seconds'=>$seconds,'completed'=>$completed);}
	public static function interact($video_id,$type){if(!is_user_logged_in())return VWLB_Helpers::error('vwlb_login_required',__('Sign in to react.',VWLB_TEXT_DOMAIN),401);$type=VWLB_Helpers::enum($type,array('like','dislike','save'),'');if(!$type)return VWLB_Helpers::error('vwlb_bad_interaction',__('Invalid interaction.',VWLB_TEXT_DOMAIN));$video=VWLB_Repository::find('videos',$video_id);if(!$video||!VWLB_Security::can_view($video))return VWLB_Helpers::error('vwlb_not_found',__('Video not found.',VWLB_TEXT_DOMAIN),404);return VWLB_DB::transaction(function()use($video,$type){global $wpdb;$table=VWLB_Helpers::table('interactions');$user=get_current_user_id();if(in_array($type,array('like','dislike'),true))$wpdb->delete($table,array('user_id'=>$user,'video_id'=>$video['id'],'interaction'=>$type==='like'?'dislike':'like'));$exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE user_id=%d AND video_id=%d AND interaction=%s",$user,$video['id'],$type));if($exists){$wpdb->delete($table,array('id'=>$exists));$active=false;}else{$wpdb->insert($table,array('user_id'=>$user,'video_id'=>$video['id'],'interaction'=>$type,'created_at'=>VWLB_Helpers::now(),'updated_at'=>VWLB_Helpers::now()));$active=true;}foreach(array('like','dislike') as $count_type){$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE video_id=%d AND interaction=%s",$video['id'],$count_type));$wpdb->update(VWLB_Helpers::table('videos'),array($count_type.'_count'=>$count),array('id'=>$video['id']));}return array('interaction'=>$type,'active'=>$active);});}
}
